42 #pragma once
43 #ifndef AI_GENERIC_PROPERTY_H_INCLUDED
44 #define AI_GENERIC_PROPERTY_H_INCLUDED
45 
46 #ifdef __GNUC__
47 #    pragma GCC system_header
48 #endif
49 
50 #include <assimp/Hash.h>
51 #include <assimp/ai_assert.h>
52 #include <assimp/Importer.hpp>
53 
54 #include <map>
55 
56 // ------------------------------------------------------------------------------------------------
57 template <class T>
58 inline bool SetGenericProperty(std::map<unsigned int, T> &list,
59         const char *szName, const T &value) {
60     ai_assert(nullptr != szName);
61     const uint32_t hash = SuperFastHash(szName);
62 
63     typename std::map<unsigned int, T>::iterator it = list.find(hash);
64     if (it == list.end()) {
65         list.insert(std::pair<unsigned int, T>(hash, value));
66         return false;
67     }
68     (*it).second = value;
69 
70     return true;
71 }
72 
73 // ------------------------------------------------------------------------------------------------
74 template <class T>
75 inline const T &GetGenericProperty(const std::map<unsigned int, T> &list,
76         const char *szName, const T &errorReturn) {
77     ai_assert(nullptr != szName);
78     const uint32_t hash = SuperFastHash(szName);
79 
80     typename std::map<unsigned int, T>::const_iterator it = list.find(hash);
81     if (it == list.end()) {
82         return errorReturn;
83     }
84 
85     return (*it).second;
86 }
87 
88 // ------------------------------------------------------------------------------------------------
89 // Special version for pointer types - they will be deleted when replaced with another value
90 // passing nullptr removes the whole property
91 template <class T>
92 inline void SetGenericPropertyPtr(std::map<unsigned int, T *> &list,
93         const char *szName, T *value, bool *bWasExisting = nullptr) {
94     ai_assert(nullptr != szName);
95     const uint32_t hash = SuperFastHash(szName);
96 
97     typename std::map<unsigned int, T *>::iterator it = list.find(hash);
98     if (it == list.end()) {
99         if (bWasExisting) {
100             *bWasExisting = false;
101         }
102 
103         list.insert(std::pair<unsigned int, T *>(hash, value));
104         return;
105     }
106     if ((*it).second != value) {
107         delete (*it).second;
108         (*it).second = value;
109     }
110     if (!value) {
111         list.erase(it);
112     }
113     if (bWasExisting) {
114         *bWasExisting = true;
115     }
116 }
117 
118 // ------------------------------------------------------------------------------------------------
119 template <class T>
120 inline bool HasGenericProperty(const std::map<unsigned int, T> &list,
121         const char *szName) {
122     ai_assert(nullptr != szName);
123     const uint32_t hash = SuperFastHash(szName);
124 
125     typename std::map<unsigned int, T>::const_iterator it = list.find(hash);
126     if (it == list.end()) {
127         return false;
128     }
129 
130     return true;
131 }
132 
133 #endif // !! AI_GENERIC_PROPERTY_H_INCLUDED
